import{_ as o,o as a,c as r,ag as s}from"./chunks/framework.TQKaXlFR.js";const p=JSON.parse('{"title":"用户导入与导出","description":"","frontmatter":{},"headers":[],"relativePath":"features/bulk.md","filePath":"features/bulk.md"}'),t={name:"features/bulk.md"};function c(d,e,i,l,n,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="用户导入与导出" tabindex="-1">用户导入与导出 <a class="header-anchor" href="#用户导入与导出" aria-label="Permalink to &quot;用户导入与导出&quot;">​</a></h1><p>入口仍是 <strong>系统管理 → 用户管理</strong> 的导入模板、导入和导出按钮。本能力面向受控的用户表格，不是任意实体批量导入框架。</p><h2 id="身份与文件准备" tabindex="-1">身份与文件准备 <a class="header-anchor" href="#身份与文件准备" aria-label="Permalink to &quot;身份与文件准备&quot;">​</a></h2><p>模板和导出使用 <code>system:user:list</code>，导入使用 <code>system:user:add</code>。角色标识须是当前允许分配的既有角色；开启租户时，不通过文件指定任意tenant或超级管理员归属。</p><p>下载当前版本模板，保持五个表头及顺序：<strong>用户账号、用户昵称、邮箱、手机号码、角色标识</strong>。最多1000数据行。使用中性验证数据或已授权的真实数据；不上传密码列、私有密钥或其他业务表。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><ol><li>从页面下载模板，填写字段，不重命名或插入额外表头。</li><li>先核对重复账号、手机、角色与当前租户范围，再选择文件导入。</li><li>等待完整响应；导入请求超时配置为120秒，不在等待时反复点击。</li><li>按响应行号修正失败行，而不是整份无条件重导。导入新账号当前为“待激活”的禁用状态，系统生成随机密码且不回显；检查角色后，由授权管理员重置并安全交付一次性密码，再编辑启用，不能假定导入后即可登录。</li><li>导出使用当前查询筛选，下载返回Blob；不要假定只导出当前分页选中项。</li></ol><h2 id="结果契约与恢复" tabindex="-1">结果契约与恢复 <a class="header-anchor" href="#结果契约与恢复" aria-label="Permalink to &quot;结果契约与恢复&quot;">​</a></h2><p><code>POST /system/user/import</code> 的 multipart字段名为 <code>file</code>。响应包含 <code>totalRows/successCount/failureCount/skippedCount/rows</code>；每行包含工作表 <code>rowNumber</code>、<code>status</code>（success/failed/skipped）、<code>field</code>和<code>reason</code>。成功HTTP或业务码不等于所有行都成功，必须读汇总与逐行结果。</p><p>表头或行数错误先重新按模板生成；业务字段错误按field/reason修改。重复提交还受到限流和防重复提交约束，等待提示后再试。导入有部分成功时先核对列表，避免制造重复账号。原始表格和导出文件包含用户资料，按组织的文件访问规则保存与清理。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><ul><li>API：<code>apps/web-ele/src/api/system/user.ts</code>（<code>UserImportSummary</code>、<code>importUsers</code>、<code>exportUsers</code>）。</li><li>Controller：<code>system-admin/src/main/java/com/xinghuiTec/controller/SysUserController.java</code>（<code>importUsers</code>、<code>downloadTemplate</code>）。</li><li>解析：<code>system-admin/src/main/java/com/xinghuiTec/listener/SysUserImportListener.java</code>（<code>REQUIRED_HEADERS</code>、<code>MAX_IMPORT_ROWS</code>）。</li><li>业务接口：<code>system-admin/src/main/java/com/xinghuiTec/service/SysUserService.java</code>。</li></ul>',12)])])}const h=o(t,[["render",c]]);export{p as __pageData,h as default};
